    pq = []

    for i in range(r):
        for j in range(c):
            if grid[i][j] == 'X':
                heapq.heappush(pq, (0, i, j))
                dist[i][j] = 0

    while pq:
        d, x, y = heapq.heappop(pq)
        if d > dist[x][y]:
            continue
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
